function CountInt(values: seq<object>): int
{
    var count := 0;
    var i := 0;
    while i < |values|
        invariant 0 <= count <= i
        invariant i <= |values|
    {
        if values[i] is int {
            count := count + 1;
        }
        i := i + 1;
